parameters.jsCode:
return items.map((item) => {
  const clean = String(item.json.intent_source_clean || '').trim();
  const raw = String(item.json.text_normalized || item.json.callback_data || '').trim().toLowerCase();
  const callback = String(item.json.callback_data || '').trim();
  let intent = String(item.json.intent_key || 'unknown');

  if (clean === 'язык / jezik / lang' || clean === 'lang' || clean === 'jezik / lang / язык' || clean === 'ru/en/rs' || clean === 'ru en rs' || raw === '🌐 язык / jezik / lang' || raw === '🇷🇺🇬🇧🇷🇸 ru/en/rs') {
    intent = 'change_language';
  }

  if (
    ['инструкция', 'instruction', 'uputstvo'].includes(clean) ||
    ['ℹ️ инструкция', 'ℹ️ instruction', 'ℹ️ uputstvo'].includes(raw)
  ) {
    intent = 'menu_instruction';
  }

  if (callback.startsWith('onb_')) {
    intent = callback;
  }

  // Human handoff is not implemented yet (chat_sessions relay is a stub),
  // so manager requests land on the contacts section instead of the AI.
  if (intent === 'talk_to_manager') {
    intent = 'menu_contacts';
  }

  // A phone number shared through the "share my number" button.
  if (String(item.json.input_type || '') === 'contact') {
    intent = 'lead_contact_shared';
  }

  // Marketing cases: inline buttons carry the case key, e.g. mcase_elis.
  let marketingCaseKey = '';
  const mcase = /^mcase_([a-z0-9_-]{1,40})$/.exec(callback);
  if (mcase) {
    intent = 'marketing_case';
    marketingCaseKey = mcase[1];
  }
  if (callback === 'mcases') {
    intent = 'menu_marketing_cases';
  }

  return {
    json: {
      ...item.json,
      intent_key: intent,
      marketing_case_key: marketingCaseKey
    }
  };
});

