// Telegram voice messages are usually downloaded as .oga.
// Groq Whisper accepts the same OGG/Opus payload more reliably when metadata says .ogg.
return items.map((item) => {
  if (!item.binary || !item.binary.data) {
    return item;
  }

  const binary = item.binary.data;
  const currentName = String(binary.fileName || 'voice.oga');
  let normalizedName = currentName.replace(/\.oga$/i, '.ogg');

  if (normalizedName === currentName && !/\.ogg$/i.test(currentName)) {
    normalizedName = `${currentName}.ogg`;
  }

  binary.fileName = normalizedName;
  binary.fileExtension = 'ogg';
  binary.mimeType = 'audio/ogg';

  return item;
});

return items.map((item) => {
  let text = String(item.json.ai_reply_text || item.json.output || item.json.text || '').trim();

  const placeholders = [];
  const stash = (value) => {
    const token = `@@HTMLTOKEN${placeholders.length}@@`;
    placeholders.push(value);
    return token;
  };
  const restore = (value) => value.replace(/@@HTMLTOKEN(\d+)@@/g, (_, idx) => placeholders[Number(idx)] || '');
  const escapeHtml = (value) => value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  text = text.replace(/\r\n/g, '\n');

  text = text.replace(/<a\s+href="[^"]+">.*?<\/a>/gis, (match) => stash(match));
  text = text.replace(/<\/?(?:b|i|u|s|code|pre)>/gi, (match) => stash(match));

  text = text.replace(/```([\s\S]*?)```/g, (_, block) => stash(`<pre>${escapeHtml(String(block).trim())}</pre>`));
  text = text.replace(/`([^`]+)`/g, (_, code) => stash(`<code>${escapeHtml(String(code).trim())}</code>`));
  text = text.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, label, url) => stash(`<a href="${String(url)}">${escapeHtml(String(label).trim())}</a>`));

  text = text.replace(/^\s{0,3}#{1,6}\s+(.+)$/gm, '<b>$1</b>');
  text = text.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  text = text.replace(/__(.+?)__/g, '<b>$1</b>');
  text = text.replace(/(^|\n)\s*[-*]\s+/g, '$1• ');

  text = text.replace(/<(?!\/?(?:b|i|u|s|code|pre)\b|a\s+href=|\/a>)/gi, '&lt;');
  text = restore(text);
  text = text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

  item.json.ai_reply_text = text;
  item.json.ai_reply_text_sanitized = text;
  return item;
});

