={{ ((j, title, html) => {
  const esc = (v) => {
    const s = String(v === undefined || v === null ? '' : v);
    return html ? s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : s;
  };
  const name = String(j.first_name || '').trim();
  const lines = [
    title,
    '',
    'Пользователь: ' + esc(name || '—') + (j.username ? ' (@' + esc(j.username) + ')' : ' (без username)') + ', id ' + esc(j.user_id),
    'Язык: ' + esc(j.language || 'ru')
  ];
  if (j.entry_point) lines.push('Источник: ' + esc(j.entry_point));
  if (j.contact_phone) lines.push('Телефон: ' + esc(j.contact_phone));
  if (j.profile_answers) {
    lines.push('', 'Ответы в разборе:');
    String(j.profile_answers).split('\n').filter(Boolean).forEach((a) => lines.push('• ' + esc(a)));
  }
  if (j.profile_service) lines.push('', 'Потенциальная услуга: ' + esc(j.profile_service));
  if (j.lead_text) {
    lines.push('', 'Сообщение пользователя:', '«' + esc(j.lead_text) + '»');
  } else {
    lines.push('', 'Описания бизнеса от пользователя пока нет.');
  }
  lines.push('', 'Lead ID: ' + esc(j.lead_id || '—'));
  if (j.username) {
    lines.push('Написать: https://t.me/' + esc(j.username));
  } else if (html) {
    lines.push('Написать: <a href="tg://user?id=' + esc(j.user_id) + '">открыть профиль</a> (username нет' + (j.contact_phone ? ')' : ', телефон не оставлен)'));
  } else {
    lines.push('Написать: tg://user?id=' + esc(j.user_id) + ' (username нет' + (j.contact_phone ? ')' : ', телефон не оставлен)'));
  }
  return lines.join('\n');
})($json, '🔥 Новая заявка на бесплатный аудит', true) }}

